def records():
    keys = ["job_id_global", "disposition", "main_duty", "evidence_field", "evidence_quote", "reason", "family_assessment", "policy_reference"]
    result = []
    for line in ASSESSMENTS.splitlines():
        if line:
            values = line.split("|")
            if len(values) != len(keys):
                raise ValueError(f"Assessment columns: {values[0]}")
            result.append(dict(zip(keys, values, strict=True)))
    return result
